// 판단 도구 · '지금 어디쯤' 종목 현황판 + 판단 일지(날짜·근거·반대 근거·재검토 조건, 그 후 결과 대조) + 기업 노트(app.js)
let journal=[];try{const j=JSON.parse(localStorage.getItem('longview-journal-v1'));if(Array.isArray(j))journal=j}catch{}
let judgeUI={symbol:'VOO',edit:null,prefill:null,filter:'전체'};
const STANCES=['매수','추가 매수','보유','비중 축소','매도','관망'];
let snapCache={asOf:null,map:{}};
function saveJournal(){try{localStorage.setItem('longview-journal-v1',JSON.stringify(journal));return true}catch{toast('일지를 저장할 수 없습니다. 대시보드에서 백업을 내려받아 주세요.');return false}}
function snapshots(){if(snapCache.asOf!==MARKET_HISTORY.asOf){const voo=MARKET_HISTORY.symbols.VOO?.rows;snapCache={asOf:MARKET_HISTORY.asOf,map:Object.fromEntries(Object.entries(MARKET_HISTORY.symbols).map(([s,d])=>[s,IND.snapshot(d.rows,voo)]))}}return snapCache.map}
const fp=(x,d=1)=>x==null||!Number.isFinite(x)?'–':(x>0?'+':'')+(x*100).toFixed(d)+'%';
const signClass=x=>x==null?'':x>0?'pos':x<0?'neg':'';
function judge(){return head('판단 도구 & 노트','숫자로 지금 위치를 확인하고, 판단을 근거·반대 근거와 함께 날짜로 남깁니다. 나중에 결과와 대조하는 것이 이 화면의 목적입니다.')+`<div class="topic-chips subtabs"><button class="chip ${tab==='now'?'selected':''}" data-tab="now">지금 어디쯤</button><button class="chip ${tab==='journal'?'selected':''}" data-tab="journal">판단 일지 <small>${journal.length?`(${journal.length})`:''}</small></button><button class="chip ${tab==='notes'?'selected':''}" data-tab="notes">기업 분석 노트 <small>${state.noteList.length?`(${state.noteList.length})`:''}</small></button></div>`+(tab==='journal'?journalView():tab==='notes'?notebook():judgeNow())}
function macroStrip(){if(typeof MACRO_HISTORY==='undefined'||!MACRO_HISTORY.series||!Object.keys(MACRO_HISTORY.series).length)return '';const S=MACRO_HISTORY.series;const item=(id,label,fmt)=>{const s=S[id];if(!s)return '';const rows=s.rows,last=rows.at(-1);const i=IND.idxOnOrBefore(rows,IND.shiftDate(last[0],{months:-1}));const prev=i>=0?rows[i][1]:null;const d=prev==null?null:last[1]-prev;const dtxt=d==null?'':s.unit==='%'?d.toFixed(2)+'%p':s.unit==='pt'?d.toFixed(1):(d/prev*100).toFixed(1)+'%';return `<div><span class="tag">${label}</span><p class="judge-value">${fmt(last[1])}${d==null?'':` <small class="${d>0?'pos':d<0?'neg':''}">(1개월 ${d>0?'+':''}${dtxt})</small>`}</p><p class="note">${last[0]}</p></div>`};return `<section class="panel" style="margin-bottom:22px"><span class="tag">MACRO · FRED · 매주 갱신</span><h3 style="margin-top:10px">금리·달러·변동성은 지금</h3><div class="judge-cards" style="margin:12px 0 6px">${item('DGS2','2년물 금리',v=>v.toFixed(2)+'%')}${item('DGS10','10년물 금리',v=>v.toFixed(2)+'%')}${item('DGS30','30년물 금리',v=>v.toFixed(2)+'%')}${item('VIXCLS','VIX',v=>v.toFixed(1))}${item('DTWEXBGS','달러 인덱스(광의)',v=>v.toFixed(1))}</div><p class="note">금리가 오르면 미래 현금의 현재가치가 낮아지고 차입비용이 커집니다(수업 ‘금리와 주식가치’). 장기 금리의 방향과 수준, VIX의 급등 여부를 보되 숫자 하나로 시장을 예측하지 마세요.</p></section>`}
function judgeNow(){const snaps=snapshots();const rowsHtml=Object.entries(MARKET_HISTORY.symbols).map(([s,d])=>{const x=snaps[s];if(!x)return '';return `<tr class="${s===judgeUI.symbol?'active':''}" data-judge-symbol="${s}" tabindex="0"><th>${esc(d.name)}<br><small>${s} · ${x.date.slice(5)}</small></th><td>${x.price>=1000?x.price.toLocaleString('en-US',{maximumFractionDigits:0}):x.price.toFixed(2)}</td><td class="${signClass(x.r1m)}">${fp(x.r1m)}</td><td class="${signClass(x.vsM200)}">${fp(x.vsM200)}</td><td class="${signClass(x.fromHigh)}">${fp(x.fromHigh)}</td><td>${x.rsi==null?'–':x.rsi.toFixed(0)}</td><td class="${signClass(x.r1y)}">${fp(x.r1y)}</td><td class="${signClass(x.cagr3)}">${fp(x.cagr3)}</td><td class="${signClass(x.rel1y)}">${fp(x.rel1y)}</td></tr>`}).join('');
 return `<div class="note-banner">기준일 ${MARKET_HISTORY.asOf} 종가 · 매주 자동 갱신 · 수익률은 배당 포함 조정종가, 가격은 실제 종가 · 어떤 칸도 매수·매도 신호가 아닙니다. 줄을 누르면 아래에 해설이 열립니다.</div><section class="panel"><div class="training-table-wrap"><table class="training-table judge-table"><thead><tr><th>종목</th><th>종가</th><th>1개월</th><th>200일선 대비</th><th>52주 고점 대비</th><th>RSI 14</th><th>1년</th><th>3년 연환산</th><th>VOO 대비 1년</th></tr></thead><tbody>${rowsHtml}</tbody></table></div><p class="note">읽는 순서 제안: ① 200일선 위인가 아래인가 ② 고점에서 얼마나 내려왔나 ③ 시장(VOO)과 비교해 더 강한가 약한가 ④ 그 이유를 사업에서 설명할 수 있는가. ④는 표에 없습니다. 그래서 일지가 필요합니다.</p></section>${macroStrip()}${judgeDetail(judgeUI.symbol)}`}
function judgeDetail(sym){const x=snapshots()[sym],d=MARKET_HISTORY.symbols[sym];if(!x)return '';const align=x.m200==null?'':x.adj>x.m20&&x.m20>x.m50&&x.m50>x.m200?' · 정배열(가격>20>50>200일선)':x.adj<x.m20&&x.m20<x.m50&&x.m50<x.m200?' · 역배열':' · 혼합 배열';const gap20=x.m20?` · 20일선 이격도 ${(x.adj/x.m20*100).toFixed(1)}%`:'';const trend=x.m200==null?'200일선을 계산할 자료가 아직 부족합니다.':`${x.vsM200>=0?'200일선 위':'200일선 아래'} ${fp(x.vsM200)} · 50일선 ${fp(x.vsM50)} · 200일선 기울기(20거래일) ${x.slope200==null?'–':x.slope200>0.002?'상승':x.slope200<-0.002?'하락':'평평'}${align}${gap20}`;
 const cards=[
  ['추세',trend,'200일선 아래라면 이 종목만 내려온 것인지, 시장 전체가 내려온 것인지 VOO 줄과 비교하세요. 정배열이라도 20일선 이격도가 110%를 넘으면 평균에서 많이 떨어진 상태라 추격 매수보다 눌림을 기다리는 쪽이 관행입니다. 추세추종 규칙이 과거 이 종목에서 어땠는지는 훈련실 200일선 전략으로 확인하세요.'],
  ['위치',`52주 고점 대비 ${fp(x.fromHigh)} · 52주 저점 대비 ${fp(x.fromLow)} · 1년 최대 낙폭 ${(x.mdd1y*100).toFixed(1)}%`,'고점 대비 −20%는 ‘사다리 분할매수’ 같은 규칙이 발동하는 구간일 수 있지만, 먼저 가설이 훼손된 하락인지 구분해야 합니다. 훼손됐다면 싸진 것이 아닙니다.'],
  ['모멘텀',`RSI(14) ${x.rsi==null?'–':x.rsi.toFixed(0)} · 1주 ${fp(x.r1w)} · 1개월 ${fp(x.r1m)} · 3개월 ${fp(x.r3m)}`,'RSI 70 위는 강한 추세에서 오래 유지되고, 30 아래는 반등을 약속하지 않습니다. 장기 투자자에게 RSI는 ‘지금 서두를 이유가 있는가’를 묻는 정도로 쓰세요.'],
  ['상대강도',`1년 수익률 ${fp(x.r1y)} · VOO 대비 ${fp(x.rel1y)}`,'시장보다 1년간 뒤졌다면 그 이유를 한 문장으로 설명할 수 있어야 합니다. 설명할 수 없다면 보유 근거를 다시 적을 때입니다.'],
  ['변동성',`ATR(14)/가격 ${x.atrPct==null?'–':(x.atrPct*100).toFixed(2)+'%'}`,'하루 평균 흔들림입니다. 전체 자산의 몇 %를 이 종목에 두어야 하루 손익을 감당할 수 있는지 계산해 보세요(수업 ‘낙폭에 대응하기’).'],
  ['장기 성과',`3년 연환산 ${fp(x.cagr3)} · 5년 연환산 ${fp(x.cagr5)}`,'배당 포함 조정종가 기준입니다. 긴 기간의 좋은 성과는 이미 가격에 기대가 들어 있다는 뜻이기도 합니다.']
 ];
 return `<section class="panel" style="margin-top:22px"><span class="tag">${sym} · 기준일 ${x.date}</span><h2 style="margin:10px 0">${esc(d.name)} — 숫자가 말하는 것, 말하지 않는 것</h2><div class="judge-cards">${cards.map(([t,v,n])=>`<div><span class="tag">${t}</span><p class="judge-value">${v}</p><p class="note">${n}</p></div>`).join('')}</div><div class="calc-result"><h3>표에 없는 네 가지 — 일지에 적을 것</h3><ul class="note" style="margin:0"><li><b>사업</b>: 최근 실적에서 매출·이익률·현금흐름은 가설대로 움직였는가?</li><li><b>가격에 담긴 기대</b>: PER(기준 명시)·FCF 수익률을 원문에서 확인하고 적습니다. 이 앱은 재무 데이터를 제공하지 않습니다.</li><li><b>반대 근거</b>: 지금 사지(팔지) 말아야 할 이유 하나.</li><li><b>틀렸다고 볼 조건</b>: 어떤 숫자가 나오면 이 판단을 접을 것인가, 언제 다시 볼 것인가.</li></ul></div><details class="research-detail"><summary>가격에 담긴 기대 계산 · 예상 EPS × 적정 멀티플</summary><p class="note">예상 EPS와 멀티플은 이 앱이 제공하지 않습니다. 회사 IR·공시, 증권사 자료에서 확인해 직접 넣으세요. 결과는 ‘내 가정의 결과’이지 적정가가 아닙니다.</p><div class="two-col"><label class="field">현재가 (USD)<input id="fvPrice" type="number" step="0.01" value="${x.price.toFixed(2)}"></label><label class="field">12개월 예상 EPS (USD)<input id="fvEps" type="number" step="0.01" placeholder="예: 6.20"></label><label class="field">적정 PER 멀티플 (예: 5년 평균 PER)<input id="fvMult" type="number" step="0.1" placeholder="예: 28"></label><label class="field">예상 EPS 성장률 (%, 연)<input id="fvGrowth" type="number" step="0.1" placeholder="예: 25"></label></div><div id="fvResult" class="calc-result">세 칸을 채우면 현재 PER·PEG·가정 적정주가와 괴리율이 나옵니다.</div><div class="actions"><button class="secondary" id="fvToJournal" disabled>이 계산을 일지 메모에 넣기 →</button></div></details><div class="actions"><button class="primary" data-journal-new="${sym}">이 종목으로 판단 일지 쓰기 →</button><button class="secondary" data-chart-symbol="${sym}">차트 보기</button><button class="secondary" data-go="resources" data-go-tab="research">공시·IR 찾는 법</button></div></section>`}
function priceOn(sym,date){const d=MARKET_HISTORY.symbols[sym];if(!d)return null;const i=IND.idxOnOrBefore(d.rows,date);return i>=0?d.rows[i]:null}
function journalOutcome(e){const d=MARKET_HISTORY.symbols[e.symbol];if(!d||!e.price)return null;const last=d.rows.at(-1);const p0=Number(e.price);if(!(p0>0)||e.date>last[0])return null;const chg=last[4]/p0-1;const v0=priceOn('VOO',e.date),v1=MARKET_HISTORY.symbols.VOO?.rows.at(-1);const voo=v0&&v1?v1[4]/v0[4]-1:null;const days=Math.round((new Date(last[0])-new Date(e.date))/86400000);return {chg,voo,days,last:last[0],price:last[4]}}
function journalView(){const e=judgeUI.edit?journal.find(x=>x.id===judgeUI.edit):null;const today=new Date().toISOString().slice(0,10);const sym=e?.symbol||judgeUI.prefill||judgeUI.symbol;const preVal=e?.valuation||judgeUI.prefillValuation||'';const auto=priceOn(sym,e?.date||today);const symbols=Object.keys(MARKET_HISTORY.symbols);const known=symbols.includes(sym);const overdue=journal.filter(x=>x.recheck&&x.recheck<=today).length;const list=journal.filter(x=>judgeUI.filter==='전체'||x.symbol===judgeUI.filter).sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id);
 return `<div class="note-banner">판단 일지는 이 브라우저에 저장됩니다. 수록 종목이면 ‘그 후 결과’를 기준일 종가로 자동 계산합니다(배당 제외, 실제 체결가 아님). 대시보드의 백업에 포함됩니다.</div><section class="panel"><span class="tag">${e?'기록 수정':'새 판단 기록'}</span><h2 style="margin:10px 0">${e?e.date+' · '+esc(e.symbol):'오늘의 판단을 적습니다'}</h2><div class="two-col"><label class="field">날짜<input id="jDate" type="date" value="${e?.date||today}" max="${today}"></label><label class="field">종목<select id="jSymbol">${symbols.map(s=>`<option value="${s}" ${s===sym?'selected':''}>${MARKET_HISTORY.symbols[s].name} · ${s}</option>`).join('')}<option value="__other" ${known?'':'selected'}>직접 입력</option></select></label><label class="field ${known?'hidden':''}" id="jOtherWrap">티커 또는 이름<input id="jOther" value="${known?'':esc(sym)}" placeholder="예: AVGO"></label><label class="field">판단 시점 가격 (USD)<input id="jPrice" type="number" step="0.01" min="0" value="${e?.price??(auto?auto[4]:'')}"><small class="note" id="jPriceNote">${auto?`${auto[0]} 종가를 자동으로 넣었습니다. 바꿀 수 있습니다.`:'수록 종목이 아니면 직접 입력하세요.'}</small></label><label class="field">판단<select id="jStance">${STANCES.map(s=>`<option ${e?.stance===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">다시 볼 날짜<input id="jRecheck" type="date" value="${e?.recheck||IND.shiftDate(today,{months:3})}"></label></div><label class="field">근거 (사실과 해석을 나눠서)<textarea id="jReason" placeholder="예: 200일선 위, 고점 대비 −8%. 2분기 매출 +56%, 영업이익률 유지. 가격은 선행 PER 35배(원문 확인 10/16).">${esc(e?.reason||'')}</textarea></label><div class="two-col"><label class="field">반대 근거 (지금 하지 말아야 할 이유)<textarea id="jCounter" placeholder="예: 1년 수익률이 VOO를 60%p 앞서 기대가 이미 높다. 경쟁사 신제품.">${esc(e?.counter||'')}</textarea></label><label class="field">틀렸다고 볼 조건<textarea id="jInvalid" placeholder="예: 다음 분기 매출 성장률 30% 아래, 또는 200일선 아래서 한 달 이상.">${esc(e?.invalid||'')}</textarea></label></div><label class="field">가격에 담긴 기대 메모 (PER·FCF 수익률 등, 기준과 확인일 포함)<input id="jValuation" value="${esc(preVal)}" placeholder="예: 선행 PER 35배(2026-10-16, 회사 IR 컨센서스 기준)"></label><div class="actions"><button class="primary" id="jSave">${e?'수정 저장':'일지에 기록'}</button>${e?'<button class="secondary" id="jCancel">취소</button>':''}</div><p class="note" id="jError" role="alert"></p></section>
 <div class="section-title"><h2>기록 ${journal.length}개${overdue?` · 다시 볼 날짜가 지난 기록 ${overdue}개`:''}</h2><label class="field" style="margin:0;min-width:180px"><select id="jFilter"><option>전체</option>${[...new Set(journal.map(x=>x.symbol))].map(s=>`<option ${judgeUI.filter===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label></div>
 ${list.length?list.map(x=>{const o=journalOutcome(x);const due=x.recheck&&x.recheck<=today;return `<article class="panel journal-entry"><div class="journal-head"><span class="stance s-${STANCES.indexOf(x.stance)}">${esc(x.stance)}</span><b>${x.date}</b> · ${esc(x.symbol)}${x.price?` @ ${Number(x.price).toLocaleString('en-US',{maximumFractionDigits:2})}`:''}${due?'<span class="badge-due">다시 볼 때</span>':x.recheck?`<small class="note">· 재검토 ${x.recheck}</small>`:''}</div><p>${esc(x.reason)}</p>${x.counter?`<p><b>반대 근거</b> · ${esc(x.counter)}</p>`:''}${x.invalid?`<p><b>틀렸다고 볼 조건</b> · ${esc(x.invalid)}</p>`:''}${x.valuation?`<p class="note">가격에 담긴 기대 · ${esc(x.valuation)}</p>`:''}${o?`<p class="judge-value">그 후 ${o.days}일 · 가격 <span class="${signClass(o.chg)}">${fp(o.chg)}</span>${o.voo!=null?` · 같은 기간 VOO <span class="${signClass(o.voo)}">${fp(o.voo)}</span>`:''} · 기준일 ${o.last} 종가 ${o.price.toFixed(2)}</p>`:''}<div class="actions" style="margin-top:8px"><button class="text-btn" data-journal-edit="${x.id}">수정</button><button class="text-btn" data-journal-delete="${x.id}">삭제</button>${MARKET_HISTORY.symbols[x.symbol]?`<button class="text-btn" data-chart-symbol="${x.symbol}">차트</button>`:''}</div></article>`}).join(''):'<section class="panel"><p class="note">아직 기록이 없습니다. 첫 기록은 보유 중인 종목에 대해 ‘보유’ 판단과 그 근거를 적는 것으로 시작해 보세요. 결과가 좋았는지보다 근거가 맞았는지를 나중에 봅니다.</p></section>'}`}
function bindJudge(){
 document.querySelectorAll('[data-journal-new]').forEach(b=>b.onclick=()=>{judgeUI.prefill=b.dataset.journalNew;judgeUI.edit=null;tab='journal';render()});
 document.querySelectorAll('[data-chart-symbol]').forEach(b=>b.onclick=()=>{chartUI.symbol=b.dataset.chartSymbol;saveChartUI();go('chart')});
 if(tab==='now'&&$('#fvEps')){const sym=judgeUI.symbol;const calcFv=()=>{const p=+$('#fvPrice').value,e=+$('#fvEps').value,m=+$('#fvMult').value,g=+$('#fvGrowth').value;const btn=$('#fvToJournal');if(!(p>0&&e!==0&&m>0)){$('#fvResult').textContent=e<0?'적자(음수 EPS) 기업은 PER로 비교하기 어렵습니다. 매출 배수나 흑자 전환 시점 가정으로 접근하세요.':'세 칸을 채우면 현재 PER·PEG·가정 적정주가와 괴리율이 나옵니다.';btn.disabled=true;return}const per=p/e,fair=e*m,gapv=p/fair-1,peg=g>0?per/g:null;const text=`현재 PER ${per.toFixed(1)}배 · 가정 적정주가 ${fair.toFixed(2)} · 현재가는 그보다 ${gapv>=0?'+':''}${(gapv*100).toFixed(1)}%${peg!=null?` · PEG ${peg.toFixed(2)}`:''}`;$('#fvResult').innerHTML=`<p class="judge-value" style="margin:0 0 6px">${text}</p><p class="note" style="margin:0">PEG 1 안팎을 ‘성장 대비 적정’으로 보는 관행이 있지만 성장률 추정 자체가 틀리기 쉽습니다. 멀티플은 금리와 시장 분위기에 따라 변합니다.</p>`;btn.disabled=false;btn.onclick=()=>{judgeUI.prefill=sym;judgeUI.prefillValuation=`${text} (EPS ${e}, 멀티플 ${m}${g?`, 성장률 ${g}%`:''} 가정 · ${new Date().toISOString().slice(0,10)})`;judgeUI.edit=null;tab='journal';render()}};['fvPrice','fvEps','fvMult','fvGrowth'].forEach(id=>$('#'+id).oninput=calcFv)}
 if(tab==='now'){document.querySelectorAll('[data-judge-symbol]').forEach(r=>{const open=()=>{judgeUI.symbol=r.dataset.judgeSymbol;render();document.querySelector('.judge-table')?.closest('.panel').nextElementSibling?.scrollIntoView({behavior:'smooth',block:'start'})};r.onclick=open;r.onkeydown=e=>{if(e.key==='Enter')open()}})}
 if(tab==='notes'){bindNotebook();return}
 if(tab!=='journal')return;
 const updateAuto=()=>{const s=$('#jSymbol').value==='__other'?$('#jOther').value.trim().toUpperCase():$('#jSymbol').value;$('#jOtherWrap').classList.toggle('hidden',$('#jSymbol').value!=='__other');const p=priceOn(s,$('#jDate').value);if(p&&!judgeUI.edit){$('#jPrice').value=p[4];$('#jPriceNote').textContent=`${p[0]} 종가를 자동으로 넣었습니다. 바꿀 수 있습니다.`}else if(!p)$('#jPriceNote').textContent='수록 종목이 아니면 직접 입력하세요.'};
 $('#jSymbol').onchange=updateAuto;$('#jDate').onchange=updateAuto;
 $('#jSave').onclick=()=>{const symbol=$('#jSymbol').value==='__other'?$('#jOther').value.trim().toUpperCase():$('#jSymbol').value;const reason=$('#jReason').value.trim();const date=$('#jDate').value;if(!symbol){$('#jError').textContent='종목을 입력하세요.';return}if(!date){$('#jError').textContent='날짜를 입력하세요.';return}if(reason.length<5){$('#jError').textContent='근거를 5자 이상 적어 주세요. 근거 없는 판단은 나중에 배울 것이 없습니다.';return}const entry={id:judgeUI.edit||Date.now(),date,symbol,price:$('#jPrice').value===''?null:Number($('#jPrice').value),stance:$('#jStance').value,reason,counter:$('#jCounter').value.trim(),invalid:$('#jInvalid').value.trim(),valuation:$('#jValuation').value.trim(),recheck:$('#jRecheck').value||''};if(judgeUI.edit){journal=journal.map(x=>x.id===entry.id?entry:x)}else journal.push(entry);if(saveJournal()){toast(judgeUI.edit?'기록을 수정했어요.':'판단을 기록했어요. 다시 볼 날짜에 결과와 대조하세요.');judgeUI.edit=null;judgeUI.prefill=null;judgeUI.prefillValuation=null;render()}};
 if($('#jCancel'))$('#jCancel').onclick=()=>{judgeUI.edit=null;render()};
 $('#jFilter').onchange=e=>{judgeUI.filter=e.target.value;render()};
 document.querySelectorAll('[data-journal-edit]').forEach(b=>b.onclick=()=>{judgeUI.edit=+b.dataset.journalEdit;render();window.scrollTo(0,0)});
 document.querySelectorAll('[data-journal-delete]').forEach(b=>b.onclick=()=>{if(confirm('이 기록을 삭제할까요? 되돌릴 수 없습니다.')){journal=journal.filter(x=>x.id!==+b.dataset.journalDelete);saveJournal();render()}});
}
